    const actions={created:'auditCreated',updated:'auditUpdated',archived:'auditArchived',restored:'auditRestored',exported:'auditExported',converted:'auditConverted',issued:'auditIssued',revision_created:'auditRevisionCreated',accepted:'auditAccepted',declined:'auditDeclined',password_reset:'auditPasswordReset','login.succeeded':'auditLoginSucceeded','login.failed':'auditLoginFailed','backup.created':'auditBackupCreated'};
    const entities={customers:'nav.customers',opportunities:'nav.pipeline',tasks:'nav.tasks',activities:'nav.activity',quotation:'nav.quotes',team:'team',authentication:'security','intake.leads':'leads','intake.rfqs':'rfqs','intake.support':'support','intake.downloads':'downloads',backup:'backup'};
