    if(dialog.open&&!await canDiscardDialog())return;
    if(!can('write'))return toast(t('readOnly'),true);const existing=row||{};const options=context||{};const isEdit=Boolean(row);state.modal={resource,id:recordId(existing),row:existing,editing:true};const formContext=state.modal;showDialog(dialogHeader(t(isEdit?'edit':Object.values(schema).find((x)=>x.resource===resource)?.title || 'create'))+'<div class="loading-state"><span class="loading-bar"></span></div>');
