  async function saveConversion(form) {const current=state.modal;const values=Object.fromEntries(new FormData(form));setFormBusy(form,true);try{const payload={create_opportunity:values.create_opportunity==='on'};if(values.customer_id)payload.customer_id=values.customer_id;if(payload.create_opportunity){payload.title=values.title;payload.currency=values.currency;const digits=minorDigits(values.currency);if((values.amount.split('.')[1]||'').length>digits)throw new Error(t('correctDecimals'));payload.amount_minor=Math.round(Number(values.amount || 0)*Math.pow(10,digits));if(values.expected_close_date)payload.expected_close_date=values.expected_close_date;}await api(current.resource+'/'+encodeURIComponent(current.id)+'/convert',{method:'POST',body:payload});toast(t('created'));state.customers=[];setFormBusy(form,false);dialog.dataset.dirty='false';await openRecord(current.resource,current.id);loadPage();}catch(error){setFormBusy(form,false);showFormError(form,error);} }
