  async function setLanguage(value) { if(!SUPPORTED_LANGUAGES.includes(value))return;if(quotesController&&(quotesController.hasUnsavedChanges()||quotesController.isBusy())){if(!await quotesController.canLeave()){document.getElementById('workspace-language').value=state.lang;return;}quotesController.discardChanges();}for(const controller of Object.values(extensionControllers)){if(controller.hasUnsavedChanges?.()||controller.isBusy?.()){if(!await controller.canLeave()){document.getElementById('workspace-language').value=state.lang;return;}controller.discardChanges?.();}}if(crmController?.canLeave&&!await crmController.canLeave()){document.getElementById('workspace-language').value=state.lang;return;}if(dialog.open&&!await canDiscardDialog()){document.getElementById('workspace-language').value=state.lang;return;}state.lang=value;const languageUrl=new URL(location.href);languageUrl.searchParams.set('lang',value);history.replaceState(null,'',languageUrl.pathname+languageUrl.search+languageUrl.hash);try{localStorage.setItem('gyutron.workspace.language.v2',value);}catch(_){}translateShell();notificationsController?.refresh();document.getElementById('breadcrumb-current').textContent=t('nav.'+state.tab);document.title=t('nav.'+state.tab)+' · GYUTRON Workspace';if(dialog.open){dialog.close();state.modal=null;}loadPage(); }
